syntax:
namespace N { /* declarations */ } 
// Access with N::name
// For nested scopes: N::Y::X
// Access base class members: N::Y::base_member
// Use scope resolution to specify exact scope: scope::name

code_example:
#include <iostream>
namespace N {
    class M {
    public:
        class B {
        public:
            void display() { std::cout << "Base class B" << std::endl; }
        };
    };
    class Y : public M::B {
    public:
        class X {
        public:
            void show() { std::cout << "Nested class X" << std::endl; }
        };
    };
}
int main() {
    N::Y::X objX;
    objX.show();
    N::Y y_obj;
    y_obj.display();
    return 0;
}
